public record Money(long minor, Currency currency) {
    public Money {                       // compact constructor: the invariant
        if (minor < 0) throw new IllegalArgumentException("amount");
    }
    public Money plus(Money other) {     // closed: Money -> Money
        if (!currency.equals(other.currency)) throw new IllegalArgumentException("currency");
        return new Money(minor + other.minor, currency);
    }
    public Money times(int factor) { return new Money(minor * factor, currency); }
    public static Money zero(Currency c) { return new Money(0, c); }
}
